import { Response } from 'express';
import { AuthRequest } from '../../types/interfaces.js';
import * as clientService from '../services/clientService.js';

export const getStatus = async (req: AuthRequest, res: Response): Promise<void> => {
  const reqStart = Date.now();
  console.log(`[API Performance] [GET /api/client/status] Request started for UID: ${req.user?.uid || 'none'}`);
  try {
    const email = req.user?.email || '';
    const uid = req.user?.uid || '';
    const targetUuid = (req.query.uuid as string) || undefined;
    const authHeader = req.headers.authorization || (req.headers as any)?.Authorization;
    const token =
      authHeader && typeof authHeader === 'string' && authHeader.startsWith('Bearer ')
        ? authHeader.split(' ')[1]
        : undefined;

    if (!email && !uid) {
      const totalTime = Date.now() - reqStart;
      console.log(`[API Performance] [GET /api/client/status] Request finished (400) | Total Execution: ${totalTime}ms | Database Time: 0ms | 3X-UI Time: 0ms`);
      res.status(400).json({ error: 'No email or uid found in token' });
      return;
    }

    const dbStart = Date.now();
    const client = await clientService.getClientStatus(email, targetUuid, uid, token);
    const dbTime = Date.now() - dbStart;

    const totalTime = Date.now() - reqStart;
    console.log(`[API Performance] [GET /api/client/status] Request finished | Total Execution: ${totalTime}ms | Database Time: ${dbTime}ms | 3X-UI Time: 0ms`);
    if (client && client._deleted === true) {
      res.json({
        success: true,
        data: null,
        deleted: true,
        deletedUuid: client.deletedUuid || targetUuid || null,
        deletedUuids: Array.isArray(client.deletedUuids) ? client.deletedUuids : [],
      });
      return;
    }
    if (client && client._noActiveConfig === true) {
      res.json({
        success: true,
        data: null,
        deletedUuids: Array.isArray(client.deletedUuids) ? client.deletedUuids : [],
      });
      return;
    }
    const deletedUuids = Array.isArray(client?.deletedUuids) ? client.deletedUuids : [];
    if (client && typeof client === 'object' && 'deletedUuids' in client) {
      const { deletedUuids: _omitted, ...cleanClient } = client;
      res.json({ success: true, data: cleanClient, deletedUuids });
      return;
    }
    res.json({ success: true, data: client, deletedUuids });
  } catch (error: any) {
    const totalTime = Date.now() - reqStart;
    console.error(`[API Performance] [GET /api/client/status] Request failed after ${totalTime}ms:`, error);
    res.status(500).json({
      error: process.env.NODE_ENV === 'production' ? 'Failed to fetch client VPN status.' : (error?.message || 'Failed to fetch client VPN status.')
    });
  }
};

export const getSubscription = async (req: AuthRequest, res: Response): Promise<void> => {
  try {
    const email = req.user?.email;
    if (!email) {
      res.status(400).json({ error: 'No email found in token' });
      return;
    }
    const uri = await clientService.getSubscriptionUri(email);
    res.json({ success: true, subscriptionUri: uri });
  } catch (error: any) {
    console.error('[ClientController] getSubscription error:', error?.message || error);
    res.status(500).json({
      error: process.env.NODE_ENV === 'production' ? 'Failed to fetch subscription link.' : (error?.message || 'Failed to fetch subscription link.')
    });
  }
};
